function escapeHtml(str) {
  return String(str)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function formatDate(iso) {
  return new Date(iso).toLocaleString(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  });
}

function isEdited(item) {
  return new Date(item.updatedAt).getTime() - new Date(item.createdAt).getTime() > 1000;
}

function avatarMarkup(name, url) {
  const safeName = escapeHtml(name || 'User');
  const safeUrl = url ? escapeHtml(url) : '';
  if (safeUrl) {
    return `<img class="avatar" src="${safeUrl}" alt="${safeName} profile picture">`;
  }
  const initial = safeName.trim().charAt(0).toUpperCase() || 'U';
  return `<div class="avatar avatar-fallback" aria-hidden="true">${initial}</div>`;
}

